mapper.select:
select o.id, o.order_no, o.user_id, o.category_id, o.dormitory_id, o.title, o.description, o.image_urls, o.worker_id, o.status, o.create_time, o.assign_time, o.finish_time, c.name as category_name, concat(d.building_no, '-', d.room_no) as dormitory_name, u.real_name as user_name, w.real_name as worker_name from repair_order o left join repair_category c on o.category_id = c.id left join dormitory d on o.dormitory_id = d.id left join sys_user u on o.user_id = u.id left join sys_user w on o.worker_id = w.id
and o.user_id = #{userId} and o.worker_id = #{workerId} and o.status = #{status} and (o.order_no like concat('%', #{keyword}, '%') or o.title like concat('%', #{keyword}, '%')) and o.category_id = #{categoryId} and u.real_name like concat('%', #{userName}, '%') and w.real_name like concat('%', #{workerName}, '%')
order by o.create_time desc limit #{start}, #{pageSize}

select count(*)
from repair_order o
left join repair_category c on o.category_id = c.id
left join sys_user u on o.user_id = u.id
left join sys_user w on o.worker_id = w.id

